package com.example.seckill.cloud.activity;
import com.example.seckill.cloud.api.OrderResultView;import com.example.seckill.cloud.common.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class SeckillController{private final SeckillEngine engine;public SeckillController(SeckillEngine e){engine=e;}@GetMapping("/api/seckill/items")ApiResponse<List<SeckillEngine.Item>>items(){return ApiResponse.ok(engine.visible(false));}@GetMapping("/api/seckill/upcoming")ApiResponse<List<SeckillEngine.Item>>upcoming(){return ApiResponse.ok(engine.visible(true));}@GetMapping("/api/seckill/path/{itemId}")ApiResponse<Map<String,String>>path(@PathVariable Long itemId,HttpServletRequest r){return ApiResponse.ok(Map.of("path",engine.path(RequestUser.require(r).id(),itemId)));}@PostMapping("/api/seckill/execute/{path}")ApiResponse<OrderResultView>execute(@PathVariable String path,@RequestBody Map<String,Long>b,HttpServletRequest r){return ApiResponse.ok(engine.execute(RequestUser.require(r).id(),b.get("itemId"),b.get("addressId"),path));}@GetMapping("/api/seckill/result/{itemId}")ApiResponse<OrderResultView>result(@PathVariable Long itemId,HttpServletRequest r){return ApiResponse.ok(engine.result(RequestUser.require(r).id(),itemId));}}
